-- GENERATED from supabase/migrations/*.sql. Do not edit. Paste the whole file into the Supabase SQL Editor once, on a new project.

-- ===== 0001_core.sql =====
-- ClinicMind Practice: core schema (phase 2).
-- Authorisation is decided here, by row level security. The front end makes no
-- authorisation decisions. Every table has RLS enabled; no policy means no access.

-- Supabase grants broad default privileges to anon/authenticated. Start from nothing.
alter default privileges in schema public revoke all on tables from anon, authenticated;
alter default privileges in schema public revoke all on functions from anon, authenticated;
alter default privileges in schema public revoke all on sequences from anon, authenticated;

-- ---------------------------------------------------------------- tables

create table cohorts (
  id            uuid primary key default gen_random_uuid(),
  name          text not null check (char_length(btrim(name)) between 1 and 80),
  supervisor_id uuid not null references auth.users (id) on delete restrict,
  invite_code   text not null unique,
  term_end      date not null,
  created_at    timestamptz not null default now()
);

create table profiles (
  id           uuid primary key references auth.users (id) on delete cascade,
  role         text not null default 'student' check (role in ('student', 'supervisor')),
  display_name text not null check (display_name = btrim(display_name) and char_length(display_name) between 1 and 40),
  cohort_id    uuid references cohorts (id) on delete set null,
  created_at   timestamptz not null default now()
);

-- client_id is generated by the browser; (user_id, client_id) makes import idempotent.
create table attempts (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null default auth.uid() references auth.users (id) on delete cascade,
  client_id    uuid not null,
  item_id      text not null,
  response     text not null,
  criteria_met boolean[] not null check (array_length(criteria_met, 1) = 3),
  created_at   timestamptz not null default now(),
  unique (user_id, client_id)
);
create index attempts_user_idx on attempts (user_id, created_at);

create table decisions (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null default auth.uid() references auth.users (id) on delete cascade,
  client_id   uuid not null,
  session_id  text not null,
  decision_id text not null,
  option_id   text,
  response    text,
  created_at  timestamptz not null default now(),
  unique (user_id, client_id)
);
create index decisions_user_idx on decisions (user_id, created_at);

create table reflections (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null default auth.uid() references auth.users (id) on delete cascade,
  client_id   uuid not null,
  module_slug text not null,
  prompt_id   text not null,
  text        text not null,
  created_at  timestamptz not null default now(),
  unique (user_id, client_id)
);
create index reflections_user_idx on reflections (user_id, created_at);

create table unlocks (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references auth.users (id) on delete cascade,
  module_slug text not null,
  level       text not null check (level in ('easy', 'medium', 'hard')),
  granted_by  uuid not null references auth.users (id),
  created_at  timestamptz not null default now(),
  unique (user_id, module_slug, level)
);

-- Never holds response text: who did what to which row, and when.
create table audit_log (
  id           uuid primary key default gen_random_uuid(),
  actor_id     uuid,
  action       text not null,
  target_table text not null,
  target_id    uuid,
  created_at   timestamptz not null default now()
);

-- Failed join attempts, for the per-account rate limit. Only join_cohort touches it.
create table join_attempts (
  id         bigint generated always as identity primary key,
  user_id    uuid not null,
  created_at timestamptz not null default now(),
  ok         boolean not null
);
create index join_attempts_user_idx on join_attempts (user_id, created_at);

alter table cohorts       enable row level security;
alter table profiles      enable row level security;
alter table attempts      enable row level security;
alter table decisions     enable row level security;
alter table reflections   enable row level security;
alter table unlocks       enable row level security;
alter table audit_log     enable row level security;
alter table join_attempts enable row level security;   -- no policy, no grant: closed to everyone but definer functions

-- ---------------------------------------------------------------- helpers

-- Used by policies. Security definer so reading profiles/cohorts here does not
-- recurse into their own policies.
create function is_supervisor_of(student uuid) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (
    select 1
    from profiles s
    join cohorts c on c.id = s.cohort_id
    where s.id = student and c.supervisor_id = auth.uid()
  )
$$;

-- Role and cohort are written only by security definer functions or by the
-- project owner. This trigger holds even if a column privilege were widened.
create function guard_profile_update() returns trigger
language plpgsql set search_path = public, pg_temp as $$
begin
  if current_user in ('authenticated', 'anon')
     and (new.role is distinct from old.role or new.cohort_id is distinct from old.cohort_id or new.id is distinct from old.id) then
    raise exception 'role and cohort cannot be changed' using errcode = '42501';
  end if;
  return new;
end $$;

create trigger profiles_guard before update on profiles
  for each row execute function guard_profile_update();

-- ---------------------------------------------------------------- policies

-- profiles: read own; supervisors read their cohort's students. No insert/delete
-- policy: rows are created by join_cohort or by the project owner.
create policy profiles_select on profiles for select to authenticated
  using (id = auth.uid() or is_supervisor_of(id));
create policy profiles_update_own on profiles for update to authenticated
  using (id = auth.uid()) with check (id = auth.uid());

-- cohorts: supervisors read their own (including the invite code). Students
-- have no access, so they never see the code. Writes only via create_cohort.
create policy cohorts_select on cohorts for select to authenticated
  using (supervisor_id = auth.uid());

-- attempts / decisions / reflections: insert and select only.
create policy attempts_select on attempts for select to authenticated
  using (user_id = auth.uid() or is_supervisor_of(user_id));
create policy attempts_insert on attempts for insert to authenticated
  with check (user_id = auth.uid());

create policy decisions_select on decisions for select to authenticated
  using (user_id = auth.uid() or is_supervisor_of(user_id));
create policy decisions_insert on decisions for insert to authenticated
  with check (user_id = auth.uid());

create policy reflections_select on reflections for select to authenticated
  using (user_id = auth.uid() or is_supervisor_of(user_id));
create policy reflections_insert on reflections for insert to authenticated
  with check (user_id = auth.uid());

-- unlocks: student reads own; supervisor reads and grants for own cohort's students.
create policy unlocks_select on unlocks for select to authenticated
  using (user_id = auth.uid() or is_supervisor_of(user_id));
create policy unlocks_insert on unlocks for insert to authenticated
  with check (is_supervisor_of(user_id) and granted_by = auth.uid());

-- audit_log: supervisors read their own actions. Written only by definer code.
create policy audit_select on audit_log for select to authenticated
  using (actor_id = auth.uid());

-- ---------------------------------------------------------------- privileges

grant select on profiles, cohorts, attempts, decisions, reflections, unlocks, audit_log to authenticated;
grant insert on attempts, decisions, reflections, unlocks to authenticated;
grant update (display_name) on profiles to authenticated;   -- not role, not cohort_id

-- ---------------------------------------------------------------- functions

-- Returns (cohort_id, error_code). Failures are RETURNED, not raised: a raised
-- exception would roll back the failed-attempt row that the rate limit counts.
-- error_code: invalid_display_name | invalid_code | cohort_closed | rate_limited
create function join_cohort(code text, display_name text)
returns table (cohort_id uuid, error_code text)
language plpgsql security definer set search_path = public, pg_temp as $$
#variable_conflict use_column
declare
  uid uuid := auth.uid();
  name_clean text := btrim(coalesce(display_name, ''));
  norm text := upper(btrim(coalesce(code, '')));
  found cohorts%rowtype;
  existing profiles%rowtype;
  failures int;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;

  if char_length(name_clean) not between 1 and 40 then
    return query select null::uuid, 'invalid_display_name'::text;
    return;
  end if;

  select count(*) into failures from join_attempts j
   where j.user_id = uid and not j.ok and j.created_at > now() - interval '1 hour';
  if failures >= 10 then
    return query select null::uuid, 'rate_limited'::text;
    return;
  end if;

  select * into found from cohorts c where c.invite_code = norm;
  if found.id is null then
    insert into join_attempts (user_id, ok) values (uid, false);
    return query select null::uuid, 'invalid_code'::text;
    return;
  end if;

  if found.term_end < current_date then
    return query select null::uuid, 'cohort_closed'::text;
    return;
  end if;

  select * into existing from profiles p where p.id = uid;
  if existing.id is not null then
    -- Already has a profile: no-op. Students keep their first cohort and
    -- supervisors stay supervisors.
    return query select existing.cohort_id, null::text;
    return;
  end if;

  insert into profiles (id, role, display_name, cohort_id) values (uid, 'student', name_clean, found.id);
  insert into join_attempts (user_id, ok) values (uid, true);
  return query select found.id, null::text;
end $$;

create function create_cohort(name text, term_end date)
returns table (id uuid, invite_code text)
language plpgsql security definer set search_path = public, pg_temp as $$
#variable_conflict use_column
declare
  uid uuid := auth.uid();
  alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';   -- 32 chars, no 0 O 1 I l
  new_code text;
  new_id uuid;
  tries int := 0;
  bytes bytea;
  i int;
begin
  if uid is null or not exists (select 1 from profiles p where p.id = uid and p.role = 'supervisor') then
    raise exception 'only supervisors can create cohorts' using errcode = '42501';
  end if;
  if char_length(btrim(coalesce(name, ''))) not between 1 and 80 then
    raise exception 'invalid cohort name' using errcode = '22023';
  end if;
  if term_end is null or term_end < current_date then
    raise exception 'term end must not be in the past' using errcode = '22023';
  end if;

  loop
    -- 10 bytes of gen_random_uuid() (skipping the version/variant bytes); 256 % 32 = 0, so no bias.
    bytes := decode(replace(gen_random_uuid()::text, '-', ''), 'hex');
    new_code := '';
    for i in 0..9 loop
      new_code := new_code || substr(alphabet, (get_byte(bytes, case when i < 6 then i else i + 3 end) % 32) + 1, 1);
    end loop;
    begin
      insert into cohorts (name, supervisor_id, invite_code, term_end)
      values (btrim(name), uid, new_code, term_end)
      returning cohorts.id into new_id;
      exit;
    exception when unique_violation then
      tries := tries + 1;
      if tries > 5 then raise; end if;
    end;
  end loop;

  insert into audit_log (actor_id, action, target_table, target_id)
  values (uid, 'create_cohort', 'cohorts', new_id);

  return query select new_id, new_code;
end $$;

revoke all on function is_supervisor_of(uuid) from public;
revoke all on function join_cohort(text, text) from public;
revoke all on function create_cohort(text, date) from public;
grant execute on function is_supervisor_of(uuid) to authenticated;
grant execute on function join_cohort(text, text) to authenticated;
grant execute on function create_cohort(text, date) to authenticated;

-- ===== 0002_supervisor_views.sql =====
-- Supervisor dashboard support (phase 2, task 4).

-- Latest activity per student. security_invoker makes the view run with the
-- caller's privileges, so row level security on the three tables decides who
-- sees which student: a supervisor gets their own cohort, a student gets themselves.
create view student_activity with (security_invoker = true) as
select user_id, max(created_at) as last_active_at
from (
  select user_id, created_at from attempts
  union all select user_id, created_at from decisions
  union all select user_id, created_at from reflections
) a
group by user_id;

grant select on student_activity to authenticated;

-- A grant is audited by who and when, never by content. The trigger is security
-- definer because nobody can insert into audit_log directly.
create function audit_unlock() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  insert into audit_log (actor_id, action, target_table, target_id)
  values (new.granted_by, 'grant_unlock', 'unlocks', new.id);
  return new;
end $$;

revoke all on function audit_unlock() from public;

create trigger unlocks_audit after insert on unlocks
  for each row execute function audit_unlock();

-- ===== 0003_hardening.sql =====
-- Hardening after review of 0001 and 0002. Nothing here changes who may read what.

-- 1. No privilege for anon on anything in public, stated explicitly. Row level
--    security already returns nothing to anon; this removes the dependency on
--    default privileges being in the expected state.
revoke all on all tables in schema public from anon;
revoke all on all functions in schema public from anon;
revoke all on all sequences in schema public from anon;

-- 2. Size limits. A student writes these rows directly, so the database must
--    bound them.
alter table attempts
  add constraint attempts_response_len check (char_length(response) <= 5000),
  add constraint attempts_item_len check (char_length(item_id) between 1 and 100),
  add constraint attempts_criteria_flat check (array_ndims(criteria_met) = 1);
alter table decisions
  add constraint decisions_response_len check (response is null or char_length(response) <= 5000),
  add constraint decisions_ids_len check (
    char_length(session_id) between 1 and 100 and char_length(decision_id) between 1 and 100
    and (option_id is null or char_length(option_id) <= 100));
alter table reflections
  add constraint reflections_text_len check (char_length(text) <= 5000),
  add constraint reflections_ids_len check (
    char_length(module_slug) between 1 and 100 and char_length(prompt_id) between 1 and 100);

-- 3. "Latest attempt wins". A client may supply created_at so that progress
--    imported from the browser keeps its dates, but never a time in the future:
--    that would pin one row as the latest for ever.
create function clamp_created_at() returns trigger
language plpgsql set search_path = public, pg_temp as $$
begin
  if new.created_at is null or new.created_at > now() then
    new.created_at := now();
  end if;
  return new;
end $$;

create trigger attempts_clamp_created before insert on attempts
  for each row execute function clamp_created_at();
create trigger decisions_clamp_created before insert on decisions
  for each row execute function clamp_created_at();
create trigger reflections_clamp_created before insert on reflections
  for each row execute function clamp_created_at();

-- 4. A student whose cohort was deleted (cohort_id set to null) could not join
--    another: join_cohort treated any existing profile as final. Such a student
--    may now join. Students in a cohort keep it; supervisors are never changed.
create or replace function join_cohort(code text, display_name text)
returns table (cohort_id uuid, error_code text)
language plpgsql security definer set search_path = public, pg_temp as $$
#variable_conflict use_column
declare
  uid uuid := auth.uid();
  name_clean text := btrim(coalesce(display_name, ''));
  norm text := upper(btrim(coalesce(code, '')));
  found cohorts%rowtype;
  existing profiles%rowtype;
  failures int;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;

  if char_length(name_clean) not between 1 and 40 then
    return query select null::uuid, 'invalid_display_name'::text;
    return;
  end if;

  select count(*) into failures from join_attempts j
   where j.user_id = uid and not j.ok and j.created_at > now() - interval '1 hour';
  if failures >= 10 then
    return query select null::uuid, 'rate_limited'::text;
    return;
  end if;

  select * into found from cohorts c where c.invite_code = norm;
  if found.id is null then
    insert into join_attempts (user_id, ok) values (uid, false);
    return query select null::uuid, 'invalid_code'::text;
    return;
  end if;

  if found.term_end < current_date then
    return query select null::uuid, 'cohort_closed'::text;
    return;
  end if;

  select * into existing from profiles p where p.id = uid;
  if existing.id is not null then
    if existing.role = 'student' and existing.cohort_id is null then
      update profiles set cohort_id = found.id where id = uid;
      insert into join_attempts (user_id, ok) values (uid, true);
      return query select found.id, null::text;
      return;
    end if;
    return query select existing.cohort_id, null::text;
    return;
  end if;

  insert into profiles (id, role, display_name, cohort_id) values (uid, 'student', name_clean, found.id);
  insert into join_attempts (user_id, ok) values (uid, true);
  return query select found.id, null::text;
end $$;

revoke all on function join_cohort(text, text) from public;
grant execute on function join_cohort(text, text) to authenticated;
revoke all on function clamp_created_at() from public;

-- ===== 0004_cohort_stages.sql =====
-- Stage unlocking (multi-stage support).
-- "foundations" is always open and is never listed here. Every other stage is
-- closed to a cohort until its supervisor opens it. A row means "open".
-- Authorisation is decided here, by row level security.

create table cohort_stages (
  id         uuid primary key default gen_random_uuid(),
  cohort_id  uuid not null references cohorts (id) on delete cascade,
  stage      text not null check (stage ~ '^[a-z0-9][a-z0-9-]*$' and char_length(stage) <= 40 and stage <> 'foundations'),
  opened_by  uuid not null references auth.users (id),
  created_at timestamptz not null default now(),
  unique (cohort_id, stage)
);

alter table cohort_stages enable row level security;

-- Used by the policies. Security definer so reading profiles/cohorts here does
-- not recurse into their own policies.
create function my_cohort_id() returns uuid
language sql stable security definer set search_path = public, pg_temp as $$
  select cohort_id from profiles where id = auth.uid()
$$;

create function supervises_cohort(cohort uuid) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (select 1 from cohorts c where c.id = cohort and c.supervisor_id = auth.uid())
$$;

revoke all on function my_cohort_id() from public;
revoke all on function supervises_cohort(uuid) from public;
grant execute on function my_cohort_id() to authenticated;
grant execute on function supervises_cohort(uuid) to authenticated;

-- A student reads their own cohort's rows; a supervisor reads their cohorts'.
create policy cohort_stages_select on cohort_stages for select to authenticated
  using (cohort_id = my_cohort_id() or supervises_cohort(cohort_id));
-- Only the cohort's supervisor opens or closes a stage, and signs it.
create policy cohort_stages_insert on cohort_stages for insert to authenticated
  with check (supervises_cohort(cohort_id) and opened_by = auth.uid());
create policy cohort_stages_delete on cohort_stages for delete to authenticated
  using (supervises_cohort(cohort_id));

-- No update: a stage is open or it is not.
grant select, insert, delete on cohort_stages to authenticated;
revoke all on cohort_stages from anon;

-- Opening and closing are audited by who and when, never by content.
create function audit_cohort_stage() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if tg_op = 'INSERT' then
    insert into audit_log (actor_id, action, target_table, target_id)
    values (new.opened_by, 'open_stage', 'cohort_stages', new.id);
    return new;
  end if;
  insert into audit_log (actor_id, action, target_table, target_id)
  values (auth.uid(), 'close_stage', 'cohort_stages', old.id);
  return old;
end $$;

revoke all on function audit_cohort_stage() from public;

create trigger cohort_stages_audit_open after insert on cohort_stages
  for each row execute function audit_cohort_stage();
create trigger cohort_stages_audit_close after delete on cohort_stages
  for each row execute function audit_cohort_stage();

-- ===== 0005_reports.sql =====
-- Reports (phase 3, tasks 3-4).
-- The text of a report is NOT stored here. It lives in the owner's Google Drive,
-- written by the `reports` Edge Function; this table keeps the title, counts and
-- the Drive file id. Students cannot write to `reports` at all: the only way in
-- is the Edge Function (service role), which scans the text again first.
-- Authorisation is decided here, by row level security.

-- Per cohort switch. Off until the owner has confirmed the placement's policy.
-- The owner turns it on in the SQL Editor; no one can change it through the app.
alter table cohorts add column reports_enabled boolean not null default false;

create table reports (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references auth.users (id) on delete cascade,
  title         text not null check (char_length(title) between 1 and 100),
  drive_file_id text not null check (char_length(drive_file_id) between 1 and 200),
  -- Counts per rule only. Never the matched text.
  deid_summary  jsonb not null default '{}'::jsonb,
  status        text not null default 'submitted' check (status in ('submitted', 'reviewed')),
  created_at    timestamptz not null default now(),
  delete_after  date not null
);
create index reports_user_idx on reports (user_id, created_at desc);

create table feedback (
  id          uuid primary key default gen_random_uuid(),
  report_id   uuid not null references reports (id) on delete cascade,
  author_id   uuid references auth.users (id) on delete set null,   -- null = AI draft (phase 4)
  scores      jsonb not null default '{}'::jsonb,
  comments    text not null default '' check (char_length(comments) <= 10000),
  status      text not null default 'draft' check (status in ('draft', 'released')),
  created_at  timestamptz not null default now(),
  released_at timestamptz
);
create index feedback_report_idx on feedback (report_id);

alter table reports  enable row level security;
alter table feedback enable row level security;

-- reports: a student reads their own; a supervisor reads their cohort's.
-- No insert, update or delete policy: writes go through the Edge Function only.
create policy reports_select on reports for select to authenticated
  using (user_id = auth.uid() or is_supervisor_of(user_id));

-- feedback: a supervisor reads and writes it for their cohort's reports and signs it.
-- A student reads only released feedback on their own report. Drafts are never visible.
create function supervises_report(report uuid) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (select 1 from reports r where r.id = report and is_supervisor_of(r.user_id))
$$;
create function owns_report(report uuid) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (select 1 from reports r where r.id = report and r.user_id = auth.uid())
$$;
revoke all on function supervises_report(uuid) from public;
revoke all on function owns_report(uuid) from public;
grant execute on function supervises_report(uuid) to authenticated;
grant execute on function owns_report(uuid) to authenticated;

create policy feedback_select on feedback for select to authenticated
  using (supervises_report(report_id) or (status = 'released' and owns_report(report_id)));
create policy feedback_insert on feedback for insert to authenticated
  with check (supervises_report(report_id) and author_id = auth.uid());
create policy feedback_update on feedback for update to authenticated
  using (supervises_report(report_id))
  with check (supervises_report(report_id) and author_id = auth.uid());

grant select on reports to authenticated;
grant select, insert, update on feedback to authenticated;
revoke all on reports, feedback from anon;

-- ===== 0006_retention.sql =====
-- Retention and review (phase 3, tasks 4-5).
--  1. delete_after follows the cohort's term_end (+ 90 days) when the owner changes it.
--  2. feedback: scores are checked, a released review is complete and cannot go back to a draft,
--     and releasing marks the report reviewed and writes an audit row (no text in it).
-- Deleting expired reports is done by the `reports` Edge Function (it must delete the Drive file
-- too), so there is no SQL purge function here. Who may see expired reports is row level security,
-- as for every other read of `reports`.

-- ---------------------------------------------------------------- retention

create function sync_report_expiry() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  update reports r set delete_after = new.term_end + 90
  from profiles p
  where p.id = r.user_id and p.cohort_id = new.id;
  return null;
end $$;
revoke all on function sync_report_expiry() from public;

create trigger cohorts_sync_report_expiry
  after update of term_end on cohorts
  for each row when (old.term_end is distinct from new.term_end)
  execute function sync_report_expiry();

-- ---------------------------------------------------------------- feedback rules

-- At most the six dimensions of the report rubric, each scored 1 to 4.
create function feedback_scores_valid(scores jsonb) returns boolean
language sql immutable as $$
  select jsonb_typeof(scores) = 'object' and not exists (
    select 1 from jsonb_each(scores) e
    where e.key not in ('picture', 'formulation', 'link', 'process', 'self', 'ethics')
       or jsonb_typeof(e.value) <> 'number'
       or e.value::text not in ('1', '2', '3', '4')
  )
$$;
create function feedback_scores_count(scores jsonb) returns integer
language sql immutable as $$
  select case when jsonb_typeof(scores) = 'object' then (select count(*)::int from jsonb_object_keys(scores)) else 0 end
$$;

alter table feedback add constraint feedback_scores_valid check (feedback_scores_valid(scores));
alter table feedback add constraint feedback_release_complete check (
  status = 'draft'
  or (released_at is not null and btrim(comments) <> '' and feedback_scores_count(scores) = 6)
);

create function release_feedback_effects() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if tg_op = 'UPDATE' and old.status = 'released' and new.status <> 'released' then
    raise exception 'released feedback cannot go back to a draft';
  end if;
  if new.status = 'released' and (tg_op = 'INSERT' or old.status <> 'released') then
    update reports set status = 'reviewed' where id = new.report_id;
    insert into audit_log (actor_id, action, target_table, target_id)
    values (auth.uid(), 'release_feedback', 'feedback', new.id);
  end if;
  return new;
end $$;
revoke all on function release_feedback_effects() from public;

create trigger feedback_release_effects
  before insert or update on feedback
  for each row execute function release_feedback_effects();
